/**
 * Run this in Chrome DevTools Console while logged into FareHarbor (https://fareharbor.com).
 *
 * Unlike the older fetch_missing_images.js (which returns ONE image per partner —
 * the reason operators sharing a partner all show the same photo), this script
 * fetches each item's OWN photo so every operator card can be unique.
 *
 * 1. Sign into fareharbor.com (partner dashboard) in this tab.
 * 2. Open DevTools → Console → paste this entire script → Enter.
 * 3. Wait ~1–2 minutes. Final output is a JSON object you copy.
 * 4. Save the output as `unique_images.json` in /Users/raptor/miami-jetski-main.
 * 5. Run: python3 apply_unique_images.py
 *
 * Output shape: { "op_id": "FilestackHandle", ... }
 */
(async () => {
  /* eslint-disable no-console */
  const log = (...a) => console.log('%c[FH-scrape]', 'color:#00d2ff', ...a);

  // Load the work list. Try same-origin fetch first; fall back to embedded.
  let needs;
  try {
    const r = await fetch('/images_needed.json');
    if (!r.ok) throw new Error('no images_needed.json');
    needs = await r.json();
  } catch (e) {
    log('Local file unreachable; using embedded list.');
    needs = NEEDS_EMBEDDED; // replaced at build time below
  }

  log(`Scraping ${needs.length} operators across ${new Set(needs.map(n => n.partner)).size} partners`);

  // Group by partner so we only call each partner's API once.
  const byPartner = {};
  for (const n of needs) (byPartner[n.partner] = byPartner[n.partner] || []).push(n);

  // Fetch all items for a partner. The FH partner API caps page size at 100.
  async function fetchPartnerItems(slug) {
    const out = [];
    let url = `https://partner-be.fareharbor.com/api/item/?company__shortname=${encodeURIComponent(slug)}&page_size=100`;
    let safety = 0;
    while (url && safety++ < 10) {
      const r = await fetch(url, { credentials: 'include' });
      if (!r.ok) {
        log(`  ✗ ${slug}: HTTP ${r.status}`);
        return out;
      }
      const data = await r.json();
      const results = data.results || data;
      if (!Array.isArray(results)) return out;
      out.push(...results);
      url = data.next || null;
    }
    return out;
  }

  // Pull a usable filestack handle out of an item record.
  function extractHandle(item) {
    const candidates = [
      item.main_image_url,
      item.image_cdn_url,
      item.image_url,
      item.photo_url,
      item.images && item.images[0] && item.images[0].url,
      item.images && item.images[0] && item.images[0].image_url,
    ];
    for (const u of candidates) {
      if (!u) continue;
      const m = String(u).match(/filestackcontent\.com\/([A-Za-z0-9]{10,30})/);
      if (m) return m[1];
    }
    return null;
  }

  const result = {};
  const stats = { matched: 0, partnerMiss: 0, itemMiss: 0, noImage: 0 };
  const seenHandles = new Set();
  // Seed with current photo handles so we don't reassign a handle that's
  // already in use elsewhere.
  for (const n of needs) if (n.current_photo_handle) seenHandles.add(n.current_photo_handle);
  // Also avoid any handle already used elsewhere in operators.json.
  if (typeof BANNED_HANDLES !== 'undefined') for (const h of BANNED_HANDLES) seenHandles.add(h);

    // Resume support: if window.__FH_UNIQUE_IMAGES already has entries from a
  // prior partial run, skip operators we already have a handle for.
  if (typeof window.__FH_UNIQUE_IMAGES === 'object' && window.__FH_UNIQUE_IMAGES) {
    let resumed = 0;
    for (const [opId, h] of Object.entries(window.__FH_UNIQUE_IMAGES)) {
      if (h && typeof h === 'string') { result[opId] = h; seenHandles.add(h); resumed++; }
    }
    if (resumed) log(`Resuming: ${resumed} entries already collected from prior run`);
  }

  const partnersDone = new Set();
  for (const [slug, group] of Object.entries(byPartner)) {
    // Skip partners whose ALL ops already have a handle
    if (group.every(n => result[n.id])) { partnersDone.add(slug); continue; }
    log(`Partner: ${slug} (${group.length} item${group.length>1?'s':''})`);
    let items;
    try {
      items = await fetchPartnerItems(slug);
    } catch (err) {
      log(`  ✗ ${slug}: fetch error — ${err.message}. Continuing.`);
      stats.partnerMiss += group.length;
      continue;
    }
    if (!items.length) { stats.partnerMiss += group.length; continue; }
    // Index items by id (as string) for fast match
    const byId = {};
    for (const it of items) byId[String(it.pk || it.id || it.item_id)] = it;

    for (const n of group) {
      let item = byId[String(n.item_id)];
      if (!item) {
        // Some FH item-ids in our links are the booking-flow pk, not the item pk.
        // Fall back: pick any item from the partner whose image isn't already used.
        item = items.find(it => {
          const h = extractHandle(it);
          return h && !seenHandles.has(h);
        }) || items[0];
        if (!item) { stats.itemMiss++; continue; }
      }
      const handle = extractHandle(item);
      if (!handle) { stats.noImage++; continue; }
      result[n.id] = handle;
      seenHandles.add(handle);
      stats.matched++;
    }
    // Persist progress after each partner so a crash doesn't lose work.
    window.__FH_UNIQUE_IMAGES = result;
    try { localStorage.setItem('fh_unique_images_progress', JSON.stringify(result)); } catch {}
    partnersDone.add(slug);
    // Mild throttle to be polite to the FH API.
    await new Promise(r => setTimeout(r, 250));
  }

  log('---- DONE ----');
  log(`matched=${stats.matched}  partner-miss=${stats.partnerMiss}  item-miss=${stats.itemMiss}  no-image=${stats.noImage}`);
  const missingPartners = Object.keys(byPartner).filter(s => !partnersDone.has(s));
  if (missingPartners.length) {
    log(`Partners still missing (${missingPartners.length}): ${missingPartners.slice(0,20).join(', ')}${missingPartners.length>20?'...':''}`);
    log(`Tip: re-run this script — it will resume from where it left off.`);
  }
  console.log('\n========== COPY EVERYTHING BELOW ==========\n');
  console.log(JSON.stringify(result, null, 2));
  console.log('\n========== STOP COPYING ==========\n');

  // Also expose for programmatic copy
  try { await navigator.clipboard.writeText(JSON.stringify(result, null, 2)); log('Copied to clipboard.'); } catch {}
  window.__FH_UNIQUE_IMAGES = result;
})();

